<article class="rv-panel"><h2>Cliente: <?= $client ? $this->text->e($client['name']) : 'sin asignar' ?></h2>
<?php if (! $bags): ?><form class="rv-entry-form" method="post" action="<?= $this->url->href('RvBagController','save',array('plugin'=>'RvSoftware','project_id'=>$projectId)) ?>"><?= $this->form->csrf() ?><input type="hidden" name="project_id" value="<?= $projectId ?>"><input type="hidden" name="operation_key" value="<?= bin2hex(random_bytes(16)) ?>"><input type="hidden" name="operation" value="client"><label>Cliente existente<select name="client_id"><option value="0">Crear cliente con nombre nuevo</option><?php foreach ($clients as $item): ?><option value="<?= (int)$item['id'] ?>"><?= $this->text->e($item['name']) ?></option><?php endforeach ?></select></label><label>Nombre del cliente nuevo<input name="name" maxlength="200"></label><button class="btn btn-blue">Asignar cliente</button></form><?php endif ?></article>
<?php if ($client): ?><article class="rv-panel"><details><summary>Crear bolsa</summary><form class="rv-entry-form" method="post" action="<?= $this->url->href('RvBagController','save',array('plugin'=>'RvSoftware','project_id'=>$projectId)) ?>"><?= $this->form->csrf() ?><input type="hidden" name="operation" value="bag"><input type="hidden" name="project_id" value="<?= $projectId ?>"><input type="hidden" name="operation_key" value="<?= bin2hex(random_bytes(16)) ?>"><label>Nombre de la bolsa<input name="name" maxlength="200" required></label><label>Horas contratadas<input type="number" name="hours" min="0.01" step="0.01" required></label><label>Desde (opcional)<input name="from" type="date"></label><label>Hasta, inclusive (opcional)<input name="until" type="date"></label><button class="btn btn-blue">Crear bolsa</button></form></details></article><?php endif ?>
<?php foreach ($bags as $bag): ?><article class="rv-panel"><h2><?= $this->text->e($bag['name']) ?> <?= $bag['archived'] ? '· Archivada' : '' ?></h2><?php if ($bag['balance_seconds'] < 0): ?><p class="alert alert-error" role="alert">Bolsa excedida. Saldo negativo permitido; revisa una ampliación.</p><?php endif ?><p>Saldo: <?= $this->text->e(number_format($bag['balance_seconds']/3600,2,',','.')) ?> h (<?= (int)$bag['balance_seconds'] ?> s)</p><p>Vigencia: <?= $bag['valid_from'] ? (new DateTimeImmutable('@'.$bag['valid_from']))->setTimezone(new DateTimeZone('America/Bogota'))->format('Y-m-d') : 'sin inicio' ?> → <?= $bag['valid_until'] ? (new DateTimeImmutable('@'.($bag['valid_until']-1)))->setTimezone(new DateTimeZone('America/Bogota'))->format('Y-m-d') : 'sin vencimiento' ?></p>
<?php if (! $bag['archived']): ?><details><summary>Ampliar o archivar</summary><form class="rv-entry-form" method="post" action="<?= $this->url->href('RvBagController','save',array('plugin'=>'RvSoftware','project_id'=>$projectId)) ?>"><?= $this->form->csrf() ?><input type="hidden" name="bag_id" value="<?= (int)$bag['id'] ?>"><input type="hidden" name="project_id" value="<?= $projectId ?>"><input type="hidden" name="operation_key" value="<?= bin2hex(random_bytes(16)) ?>"><label>Horas adicionales<input name="hours" type="number" min="0.01" step="0.01"></label><label>Motivo<input name="reason" required></label><button class="btn btn-blue" name="operation" value="extend">Ampliar horas</button> <button class="btn" name="operation" value="archive">Archivar bolsa</button></form></details><?php endif ?>
<details><summary>Ajuste auditado de saldo</summary><form class="rv-entry-form" method="post" action="<?= $this->url->href('RvBagController','save',array('plugin'=>'RvSoftware','project_id'=>$projectId)) ?>"><?= $this->form->csrf() ?><input type="hidden" name="operation" value="adjust"><input type="hidden" name="project_id" value="<?= $projectId ?>"><input type="hidden" name="bag_id" value="<?= (int)$bag['id'] ?>"><input type="hidden" name="operation_key" value="<?= bin2hex(random_bytes(16)) ?>"><label>Segundos de ajuste (positivo acredita, negativo descuenta)<input type="number" name="seconds" step="1" required></label><label>Motivo<input name="reason" required></label><button class="btn">Registrar ajuste</button></form></details><details><summary>Historial de movimientos</summary><ul><?php foreach ($bag['entries'] as $entry): ?><li><?= $this->text->e($entry['kind']) ?> · <?= (int)$entry['seconds'] ?> s · usuario #<?= (int)$entry['actor_id'] ?> · <?= $this->text->e($entry['reason']) ?></li><?php endforeach ?></ul></details></article><?php endforeach ?>
